        ('greening', 'Професійне озеленення у Бучі, Ірпені, Гостомелі, Ворзелі та Київській області: підбір і висадка дерев, кущів, квітників під ваш ґрунт і освітлення.', 'Озеленення ділянок у Бучі, Ірпені й Київщині | Poli Valko', 'Професійне озеленення у Бучі, Ірпені, Гостомелі, Ворзелі та Київській області: підбір і висадка дерев, кущів, квітників під ваш ґрунт і освітлення.'),
        ('lawns', 'Укладання рулонного та посівного газону в Бучі, Ірпені, Гостомелі, Ворзелі та Київській області: підготовка ґрунту, вирівнювання, посів і перший догляд.', 'Укладання рулонного й посівного газону в Бучі | Poli Valko', 'Укладання рулонного та посівного газону в Бучі, Ірпені, Гостомелі, Ворзелі та Київській області: підготовка ґрунту, вирівнювання, посів і перший догляд.'),
        ('irrigation-installation', 'Проєктування й монтаж автополиву під ключ у Бучі, Ірпені, Гостомелі, Ворзелі та Київській області на обладнанні Hunter та Irritec. Гарантія Poli Valko.', 'Монтаж автополиву в Бучі, Ірпені й Київщині | Poli Valko', 'Проєктування й монтаж автополиву під ключ у Бучі, Ірпені, Гостомелі, Ворзелі та Київській області на обладнанні Hunter та Irritec. Гарантія Poli Valko.'),
        ('irrigation-service', 'Весняний запуск, продувка й консервація автополиву на зиму, ремонт форсунок і контролерів у Бучі, Ірпені, Гостомелі, Ворзелі та Київській області.', 'Сервіс, запуск і консервація автополиву в Бучі | Poli Valko', 'Весняний запуск, продувка й консервація автополиву на зиму, ремонт форсунок і контролерів у Бучі, Ірпені, Гостомелі, Ворзелі та Київській області.'),
        ('garden-care', 'Комплексний сезонний догляд за садом у Бучі, Ірпені, Гостомелі, Ворзелі та Київській області: обрізка, підживлення, аерація газону й прибирання.', 'Догляд за садом у Бучі, Ірпені й Гостомелі | Poli Valko', 'Комплексний сезонний догляд за садом у Бучі, Ірпені, Гостомелі, Ворзелі та Київській області: обрізка, підживлення, аерація газону й прибирання.'),
        ('plant-treatment', 'Професійна обробка саду від шкідників і хвороб у Бучі, Ірпені, Гостомелі, Ворзелі та Київській області сертифікованими препаратами. Виїзд Poli Valko.', 'Обробка саду й рослин у Бучі та Київщині | Poli Valko', 'Професійна обробка саду від шкідників і хвороб у Бучі, Ірпені, Гостомелі, Ворзелі та Київській області сертифікованими препаратами. Виїзд Poli Valko.')
)
UPDATE content.service_directions AS sd
SET description = v.description,
    seo_title = v.seo_title,
    seo_description = v.seo_description,
    updated_at = now()
FROM seo_services AS v
WHERE sd.code = v.code
  AND (sd.description IS DISTINCT FROM v.description
       OR sd.seo_title IS DISTINCT FROM v.seo_title
       OR sd.seo_description IS DISTINCT FROM v.seo_description);

