WITH seo_pages(slug, seo_title, seo_description) AS (
    VALUES
        ('payment-delivery', 'Доставка Новою поштою, оплата й самовивіз | Poli Valko', 'Умови доставки й оплати в Poli Valko: Нова пошта по всій Україні, безкоштовний самовивіз у Бучі (ТК «Варшавський»), оплата карткою чи при отриманні.'),
        ('returns', 'Повернення й обмін товарів протягом 14 днів | Poli Valko', 'Умови повернення та обміну товарів у магазині Poli Valko протягом 14 днів відповідно до закону України. Простий порядок звернення та підтримка.'),
        ('offer', 'Публічна оферта та умови купівлі в магазині | Poli Valko', 'Договір публічної оферти інтернет-магазину Poli Valko (ФОП Валко Віталій): порядок оформлення, оплати, доставки та повернення замовлень в Україні.'),
        ('privacy', 'Політика конфіденційності й захисту даних | Poli Valko', 'Політика конфіденційності інтернет-магазину Poli Valko: як ми обробляємо, зберігаємо й захищаємо персональні дані покупців відповідно до закону.')
)
UPDATE content.pages AS p
SET seo_title = v.seo_title,
    seo_description = v.seo_description,
    updated_at = now(),
    updated_by = 'seo-metadata-apply'
FROM seo_pages AS v
WHERE p.slug = v.slug
  AND (p.seo_title IS DISTINCT FROM v.seo_title
       OR p.seo_description IS DISTINCT FROM v.seo_description);

-- -----------------------------------------------------------------------------
-- 5. Clear generic root-only social placeholder URLs in content.contacts
--    (keeps any concrete profile URL such as https://www.facebook.com/<page>)
-- -----------------------------------------------------------------------------
UPDATE content.contacts
SET facebook = NULL,
    updated_at = now()
WHERE id = 1
  AND facebook IS NOT NULL
  AND lower(btrim(facebook)) ~ '^https?://(www\.|m\.)?facebook\.com/?$';

-- -----------------------------------------------------------------------------
-- 6. Replace legacy seeded images.unsplash.com banner URLs with local /brand/*
-- -----------------------------------------------------------------------------
WITH banner_replacements(old_url, new_url) AS (
    VALUES
        ('https://images.unsplash.com/photo-1719324923613-ff0884b031ed?auto=format&fit=crop&q=80&w=1200', '/brand/about-garden.webp'),
        ('https://images.unsplash.com/photo-1729603596055-22a2c182903b?auto=format&fit=crop&q=80&w=1200', '/brand/service-irrigation.webp'),
        ('https://images.unsplash.com/photo-1482517967863-00e15c9b44be?auto=format&fit=crop&q=80&w=1200', '/brand/polivalko-bucha.jpg')
)
UPDATE content.banners AS b
SET image_url = r.new_url,
    updated_at = now()
FROM banner_replacements AS r
WHERE b.image_url = r.old_url;

-- -----------------------------------------------------------------------------
-- 7. Normalize duplicate brand spelling/casing (Bross / Bros -> BROS)
--    Safely respects unique indexes ix_brands_normalized_name and ix_brands_slug.
-- -----------------------------------------------------------------------------
UPDATE catalog.products
SET brand = 'BROS',
    updated_at = now()
WHERE brand IS NOT NULL
  AND upper(btrim(brand)) IN ('BROSS', 'BROS')
  AND brand IS DISTINCT FROM 'BROS';

-- 7a. If a canonical BROS brand row exists alongside a BROSS row, preserve any
--     non-empty description/logo_url from BROSS and remove the duplicate row.
UPDATE catalog.brands AS target
SET name = 'BROS',
    description = COALESCE(NULLIF(btrim(target.description), ''), dup.description),
    logo_url = COALESCE(NULLIF(btrim(target.logo_url), ''), dup.logo_url)
FROM catalog.brands AS dup
WHERE target.normalized_name = 'BROS'
  AND dup.normalized_name = 'BROSS'
  AND (target.name IS DISTINCT FROM 'BROS'
       OR target.description IS DISTINCT FROM COALESCE(NULLIF(btrim(target.description), ''), dup.description)
       OR target.logo_url IS DISTINCT FROM COALESCE(NULLIF(btrim(target.logo_url), ''), dup.logo_url));

DELETE FROM catalog.brands AS dup
WHERE dup.normalized_name = 'BROSS'
  AND EXISTS (SELECT 1 FROM catalog.brands AS target WHERE target.normalized_name = 'BROS');

-- 7b. If only BROSS exists (and no BROS row or 'bros' slug), rename it cleanly.
UPDATE catalog.brands
SET name = 'BROS',
    normalized_name = 'BROS',
    slug = 'bros'
WHERE normalized_name = 'BROSS'
  AND NOT EXISTS (SELECT 1 FROM catalog.brands WHERE normalized_name = 'BROS' OR slug = 'bros');

-- 7c. Ensure canonical BROS display name casing if row exists as 'Bros' / 'bros'.
UPDATE catalog.brands
SET name = 'BROS'
WHERE normalized_name = 'BROS'
  AND name IS DISTINCT FROM 'BROS';

COMMIT;
